export const PRODUCTOS: Producto[] = RAW.map(([codigo, nombre, categoria, bultos, porBulto, total, socios, mayor, unidad, nota, lote, foto], i) => ({
  id: String(i + 1), codigo, nombre, categoria, bultos, porBulto, total, stock: total, socios, mayor, unidad, docena: null, lote, nota, foto, presentacion: "Unidad", barras: `99900000${String(i + 1).padStart(5, "0")}`,
}));
const IDX = PRODUCTOS.map((p) => ({ p, h: [norm(p.codigo), norm(p.nombre), norm(p.categoria), p.barras], w: p.nombre.split(/\s+/).map(norm).filter(Boolean) }));
export const buscar = (q: string): Producto[] => {
  const T = q.trim().split(/\s+/).map(norm).filter(Boolean);
  if (!T.length) return PRODUCTOS;
  const ok = (x: (typeof IDX)[number], z: boolean) => T.every((t) => x.h.some((f) => f.includes(t)) || (z && t.length > 3 && x.w.some((w) => lev(t, w) <= 1)));
  let r = IDX.filter((x) => ok(x, false)); if (!r.length) r = IDX.filter((x) => ok(x, true));
  const t0 = T.join(""); const sc = (x: (typeof IDX)[number]) => (x.h[0] === t0 ? 0 : x.h[0].startsWith(t0) ? 1 : x.h[0].includes(t0) ? 2 : 3);
  return r.sort((a, b) => sc(a) - sc(b) || a.p.nombre.localeCompare(b.p.nombre)).map((x) => x.p);
};
export const buscarPorCodigo = (c: string) => { const t = norm(c); return PRODUCTOS.find((p) => p.barras === c.trim() || norm(p.codigo) === t); };
export const CATEGORIAS = Array.from(new Set(PRODUCTOS.map((p) => p.categoria))).sort();
export const money = (n: number) => `$${n.toFixed(2).replace(".", ",")}`;
export const guardarReciente = (id: string) => {
  try {
    const l: string[] = JSON.parse(localStorage.getItem("recientes") || "[]");
    localStorage.setItem("recientes", JSON.stringify([id, ...l.filter((x) => x !== id)].slice(0, 8)));
  } catch {}
};
export const leerRecientes = (): Producto[] => {
  try {
    const l: string[] = JSON.parse(localStorage.getItem("recientes") || "[]");
    return l.map((id) => PRODUCTOS.find((p) => p.id === id)).filter(Boolean) as Producto[];
  } catch { return []; }
};
